+    <script>
+      const form = document.getElementById("support-form");
+      const statusMessage = document.getElementById("form-status");
+      const phonePattern = /^\+?[0-9()\s.-]{7,20}$/;
+
+      const fields = [
+        {
+          input: document.getElementById("full-name"),
+          error: document.getElementById("full-name-error"),
+          helpId: "",
+          validate(value) {
+            if (!value.trim()) {
+              return "Error: Enter your full name.";
+            }
+            return "";
+          },
+        },
+        {
+          input: document.getElementById("email-address"),
+          error: document.getElementById("email-address-error"),
+          helpId: "",
+          validate(value) {
+            if (!value.trim()) {
+              return "Error: Enter your email address.";
+            }
+            if (!this.input.validity.valid) {
+              return "Error: Enter a valid email address, like name@example.com.";
+            }
+            return "";
+          },
+        },
+        {
+          input: document.getElementById("phone-number"),
+          error: document.getElementById("phone-number-error"),
+          helpId: "phone-help",
+          validate(value) {
+            if (!value.trim()) {
+              return "";
+            }
+            if (!phonePattern.test(value.trim())) {
+              return "Error: Enter a valid phone number using digits, spaces, parentheses, periods, or hyphens.";
+            }
+            return "";
+          },
+        },
+      ];
+
+      function setStatus(message, state) {
+        statusMessage.textContent = message;
+        statusMessage.dataset.state = state || "";
+      }
+
+      function setFieldState(field, errorMessage) {
+        const describedBy = [field.helpId];
+
+        if (errorMessage) {
+          field.input.setAttribute("aria-invalid", "true");
+          field.error.textContent = errorMessage;
+          field.error.hidden = false;
+          describedBy.push(field.error.id);
+        } else {
+          field.input.removeAttribute("aria-invalid");
+          field.error.hidden = true;
+          field.error.textContent = "";
+        }
+
+        if (describedBy.filter(Boolean).length > 0) {
+          field.input.setAttribute("aria-describedby", describedBy.filter(Boolean).join(" "));
+        } else {
+          field.input.removeAttribute("aria-describedby");
+        }
+      }
+
+      function validateField(field) {
+        const errorMessage = field.validate(field.input.value);
+        setFieldState(field, errorMessage);
+        return !errorMessage;
+      }
+
+      fields.forEach((field) => {
+        field.input.addEventListener("blur", () => {
+          validateField(field);
+        });
+
+        field.input.addEventListener("input", () => {
+          if (!field.error.hidden) {
+            validateField(field);
+          }
+
+          if (statusMessage.dataset.state) {
+            setStatus("", "");
+          }
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        const firstInvalidField = fields.find((field) => !validateField(field));
+
+        if (firstInvalidField) {
+          setStatus("Please correct the highlighted fields and try again.", "error");
+          firstInvalidField.input.focus();
+          return;
+        }
+
+        setStatus("Thanks. Your support request is ready to send.", "success");
+        form.reset();
+        fields.forEach((field) => {
+          setFieldState(field, "");
+        });
+      });
+    </script>
+  </body>
+</html>
