  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <section class="support-layout" aria-labelledby="support-heading">
        <div class="hero-card">
          <p class="eyebrow">Support</p>
          <div>
            <h1 id="support-heading">Talk to our support team</h1>
            <p class="hero-copy">
              Reach out with account, billing, or product questions and our team will get back to you with a clear next step.
            </p>
          </div>
          <ul class="support-points" aria-label="Support highlights">
            <li>
              <div>
                <strong>Fast routing</strong>
                Your message goes straight to the team that can help.
              </div>
            </li>
            <li>
              <div>
                <strong>Human follow-up</strong>
                We reply with practical guidance instead of canned answers.
              </div>
            </li>
            <li>
              <div>
                <strong>Flexible contact details</strong>
                Leave a phone number if you want us to call you back.
              </div>
            </li>
          </ul>
        </div>

        <div class="form-card">
          <h2>Contact support</h2>
          <p>
            Required fields are marked with <span aria-hidden="true">*</span><span class="visually-hidden"> an asterisk</span>.
          </p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-required="true"
              />
              <p id="full-name-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                inputmode="email"
                autocomplete="email"
                required
                aria-required="true"
              />
              <p id="email-address-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                inputmode="tel"
                autocomplete="tel"
                aria-describedby="phone-help"
              />
              <p id="phone-help" class="field-help">Use digits with an optional country code, like +1 555 123 4567.</p>
              <p id="phone-number-error" class="field-error" hidden></p>
            </div>

            <div class="actions">
              <button type="submit">Send message</button>
            </div>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </form>
        </div>
      </section>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusMessage = document.getElementById("form-status");
      const phonePattern = /^\+?[0-9()\s.-]{7,20}$/;

      const fields = [
        {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          helpId: "",
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your full name.";
            }
            return "";
          },
        },
        {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          helpId: "",
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }
            if (!this.input.validity.valid) {
              return "Error: Enter a valid email address, like name@example.com.";
            }
            return "";
          },
        },
        {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-number-error"),
          helpId: "phone-help",
          validate(value) {
            if (!value.trim()) {
              return "";
            }
            if (!phonePattern.test(value.trim())) {
              return "Error: Enter a valid phone number using digits, spaces, parentheses, periods, or hyphens.";
            }
            return "";
          },
        },
      ];

      function setStatus(message, state) {
        statusMessage.textContent = message;
        statusMessage.dataset.state = state || "";
      }

      function setFieldState(field, errorMessage) {
        const describedBy = [field.helpId];

        if (errorMessage) {
          field.input.setAttribute("aria-invalid", "true");
          field.error.textContent = errorMessage;
          field.error.hidden = false;
          describedBy.push(field.error.id);
        } else {
          field.input.removeAttribute("aria-invalid");
          field.error.hidden = true;
          field.error.textContent = "";
        }

        if (describedBy.filter(Boolean).length > 0) {
          field.input.setAttribute("aria-describedby", describedBy.filter(Boolean).join(" "));
        } else {
          field.input.removeAttribute("aria-describedby");
        }
      }

      function validateField(field) {
        const errorMessage = field.validate(field.input.value);
        setFieldState(field, errorMessage);
        return !errorMessage;
      }

      fields.forEach((field) => {
        field.input.addEventListener("blur", () => {
          validateField(field);
        });

        field.input.addEventListener("input", () => {
          if (!field.error.hidden) {
            validateField(field);
          }

          if (statusMessage.dataset.state) {
            setStatus("", "");
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const firstInvalidField = fields.find((field) => !validateField(field));

        if (firstInvalidField) {
          setStatus("Please correct the highlighted fields and try again.", "error");
          firstInvalidField.input.focus();
          return;
        }

        setStatus("Thanks. Your support request is ready to send.", "success");
        form.reset();
        fields.forEach((field) => {
          setFieldState(field, "");
        });
      });
    </script>
  </body>
</html>
