    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <section class="support-layout" aria-labelledby="support-heading">
        <div class="hero-card">
          <p class="eyebrow">Support</p>
          <div>
            <h1 id="support-heading">Talk to our support team</h1>
            <p class="hero-copy">
              Reach out with account, billing, or product questions and our team will get back to you with a clear next step.
            </p>
          </div>
          <ul class="support-points" aria-label="Support highlights">
            <li>
              <div>
                <strong>Fast routing</strong>
                Your message goes straight to the team that can help.
              </div>
            </li>
            <li>
              <div>
                <strong>Human follow-up</strong>
                We reply with practical guidance instead of canned answers.
              </div>
            </li>
            <li>
              <div>
                <strong>Flexible contact details</strong>
                Leave a phone number if you want us to call you back.
              </div>
            </li>
          </ul>
        </div>

        <div class="form-card">
          <h2>Contact support</h2>
          <p>
            Required fields are marked with <span aria-hidden="true">*</span><span class="visually-hidden"> an asterisk</span>.
          </p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-required="true"
              />
              <p id="full-name-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                inputmode="email"
                autocomplete="email"
                required
                aria-required="true"
              />
              <p id="email-address-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                inputmode="tel"
                autocomplete="tel"
                aria-describedby="phone-help"
              />
              <p id="phone-help" class="field-help">Use digits with an optional country code, like +1 555 123 4567.</p>
              <p id="phone-number-error" class="field-error" hidden></p>
            </div>

            <div class="actions">
              <button type="submit">Send message</button>
            </div>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </form>
        </div>
      </section>
